#!/usr/bin/env python3
"""Compute the CSX-076_Q1 ground truth from local package records."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


TASK_ID = "CSX-076_Q1"
EVENT_ID = "CSX-076"
TARGET_FAMILY = "pakistan_monsoon_flood_load_numeric_diagnosis"
ROOT = Path(__file__).resolve().parents[3]
PACKAGE = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_2022_Pakistan_monsoon_floods.json",
    "data/event_catalogs/event_catalogs_002_04_event_specific_disaster_catalog_GDACS_event_list_for_package_time_window.json.json",
    "data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json",
    "data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_007_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_009_CHIRPS_daily_event_accumulated_precipitation.json",
]

RUBRIC = {
    "total_points": 20,
    "criteria": [
        {
            "name": "Final structured answer",
            "points": 3,
            "description": "Returns the requested JSON fields, target family, threshold state, and final label.",
            "partial_credit": "Award 1-2 points for a mostly complete JSON answer with one missing field group.",
        },
        {
            "name": "Gridded rainfall calculations",
            "points": 4,
            "description": "Reports the declared gridded comparison window, GPM 792.492 mm, CHIRPS 815.383 mm, ERA5-Land 846.553 mm, ensemble mean 818.143 mm, and that all three comparison-window means exceed 700 mm.",
            "partial_credit": "Award 2-3 points for correct means with missing or rounded ensemble arithmetic.",
        },
        {
            "name": "Point total and peak-day concentration",
            "points": 4,
            "description": "Reports 110 days, 1493.3 mm total, 150.31 mm peak day, and peak-day share 0.1007.",
            "partial_credit": "Award 2-3 points for the total and peak value without a correct ratio test; award 1 point for only one correct anchor.",
        },
        {
            "name": "Persistence metrics",
            "points": 3,
            "description": "Reports wet-day fraction 42/110=0.3818, heavy-day fraction 31/110=0.2818, and the 13-day heavy spell.",
            "partial_credit": "Award 1-2 points for two of the three persistence anchors.",
        },
        {
            "name": "Rolling-window calculation",
            "points": 2,
            "description": "Reports the maximum 14-day total of 662.76 mm and its share of 0.4438.",
            "partial_credit": "Award 1 point for the correct window total without the share, or the correct share without the total.",
        },
        {
            "name": "Threshold reasoning",
            "points": 2,
            "description": "Combines the gridded load check, peak-day share below 15 percent, and heavy-day persistence into the threshold state.",
            "partial_credit": "Award 1 point for applying only one threshold correctly.",
        },
        {
            "name": "Weak alternative rejection",
            "points": 1,
            "description": "Rejects a single-day-only or report-only explanation using the computed values.",
            "partial_credit": "Award 0.5 points for rejecting one weak alternative without a numeric reason.",
        },
        {
            "name": "Concise computed interpretation",
            "points": 1,
            "description": "Provides a short event-specific interpretation without adding new loss estimates.",
            "partial_credit": "Award 0.5 points for a correct label with overly broad prose.",
        },
    ],
}


def read_json(rel_path: str) -> Any:
    return json.loads((PACKAGE / rel_path).read_text(encoding="utf-8-sig"))


def round_float(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def iso_date(yyyymmdd: str) -> str:
    return f"{yyyymmdd[:4]}-{yyyymmdd[4:6]}-{yyyymmdd[6:]}"


def longest_run(values: list[tuple[str, float]], threshold: float) -> dict[str, Any]:
    best_len = 0
    current_len = 0
    best_end = -1
    for idx, (_, value) in enumerate(values):
        if value >= threshold:
            current_len += 1
            if current_len > best_len:
                best_len = current_len
                best_end = idx
        else:
            current_len = 0
    if best_end < 0:
        return {"days": 0, "start_date": None, "end_date": None}
    start = best_end - best_len + 1
    return {
        "days": best_len,
        "start_date": iso_date(values[start][0]),
        "end_date": iso_date(values[best_end][0]),
    }


def rolling_max(values: list[tuple[str, float]], window_days: int, total: float) -> dict[str, Any]:
    best_total = -1.0
    best_start = 0
    for idx in range(0, len(values) - window_days + 1):
        window_total = sum(value for _, value in values[idx : idx + window_days])
        if window_total > best_total:
            best_total = window_total
            best_start = idx
    best_end = best_start + window_days - 1
    return {
        "mm": round_float(best_total),
        "start_date": iso_date(values[best_start][0]),
        "end_date": iso_date(values[best_end][0]),
        "share": round_float(best_total / total, 4),
    }


def daily_point_precip_stats(rel_path: str) -> dict[str, Any]:
    data = read_json(rel_path)
    daily = data["properties"]["parameter"]["PRECTOTCORR"]
    values = [(date, float(daily[date])) for date in sorted(daily)]
    total = sum(value for _, value in values)
    max_date, max_value = max(values, key=lambda item: item[1])
    event_days = len(values)
    wet_days = sum(value >= 1 for _, value in values)
    heavy_days = sum(value >= 10 for _, value in values)
    return {
        "event_days": event_days,
        "total_mm": round_float(total),
        "peak_day_mm": round_float(max_value),
        "peak_day_date": iso_date(max_date),
        "peak_day_share": round_float(max_value / total, 4),
        "wet_days_ge_1mm": wet_days,
        "wet_day_fraction": round_float(wet_days / event_days, 4),
        "heavy_days_ge_10mm": heavy_days,
        "heavy_day_fraction": round_float(heavy_days / event_days, 4),
        "longest_heavy_spell": longest_run(values, 10),
        "max_14day": rolling_max(values, 14, total),
    }


def pakistan_flood_catalog(rel_path: str) -> dict[str, Any]:
    data = read_json(rel_path)
    for feature in data["features"]:
        props = feature["properties"]
        if props.get("iso3") == "PAK" and props.get("eventtype") == "FL":
            return {
                "name": props["name"],
                "alertlevel": props["alertlevel"],
                "fromdate": props["fromdate"],
                "todate": props["todate"],
            }
    raise RuntimeError("Pakistan flood catalog record not found")


def build_output() -> dict[str, Any]:
    event = read_json(SOURCE_FILES[0])
    anchor = read_json(SOURCE_FILES[1])["locked_event_anchor"]
    catalog = pakistan_flood_catalog(SOURCE_FILES[2])
    point = daily_point_precip_stats(SOURCE_FILES[3])
    era5 = read_json(SOURCE_FILES[4])
    gpm = read_json(SOURCE_FILES[5])
    chirps = read_json(SOURCE_FILES[6])

    gridded_means = {
        "gpm": round_float(gpm["stats"]["gpm_event_precip_mm_mean"]),
        "chirps": round_float(chirps["stats"]["chirps_event_precip_mm_mean"]),
        "era5_land": round_float(era5["stats"]["precipitation_sum_mm_mean"]),
    }
    gridded_comparison_window = {"start_date": gpm["start"], "end_date": gpm["end"]}
    if (
        gridded_comparison_window != {"start_date": chirps["start"], "end_date": chirps["end"]}
        or gridded_comparison_window != {"start_date": era5["start"], "end_date": era5["end"]}
    ):
        raise RuntimeError("Gridded precipitation products do not share a comparison window")
    ensemble_mean = round_float(sum(gridded_means.values()) / len(gridded_means))
    all_gridded_gt_700 = all(value > 700 for value in gridded_means.values())

    checks = [
        event["event_name"] == "2022 Pakistan monsoon floods",
        event["hazard_family"] == "extreme_precip_pluvial_flood",
        anchor["event_start_date"] == "2022-06-14",
        anchor["event_end_date"] == "2022-10-01",
        catalog["alertlevel"] == "Red",
        point["event_days"] == 110,
        point["total_mm"] > 1000,
        all_gridded_gt_700,
        point["peak_day_share"] < 0.15,
        point["heavy_days_ge_10mm"] >= 30,
        point["longest_heavy_spell"]["days"] >= 10,
        point["max_14day"]["share"] < 0.50,
    ]
    if not all(checks):
        raise RuntimeError(f"Ground-truth checks failed: {checks}")

    threshold_state = "all_gridded_means_gt_700mm_and_peak_day_lt_15pct"
    final_label = "persistent_monsoon_flood_load_consistent"

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": {
            "target_family": TARGET_FAMILY,
            "gridded_means_mm": gridded_means,
            "gridded_comparison_window": gridded_comparison_window,
            "ensemble_mean_mm": ensemble_mean,
            "point_rainfall": {
                "event_days": point["event_days"],
                "total_mm": point["total_mm"],
                "peak_day_mm": point["peak_day_mm"],
                "peak_day_share": point["peak_day_share"],
                "wet_day_fraction": point["wet_day_fraction"],
                "heavy_day_fraction": point["heavy_day_fraction"],
                "longest_heavy_spell_days": point["longest_heavy_spell"]["days"],
                "max_14day_share": point["max_14day"]["share"],
            },
            "threshold_state": threshold_state,
            "final_label": final_label,
        },
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": [anchor["event_start_date"], anchor["event_end_date"]],
            "catalog_alertlevel": catalog["alertlevel"],
            "gridded_comparison_window": gridded_comparison_window,
            "gridded_means_mm": gridded_means,
            "ensemble_mean_mm": ensemble_mean,
            "all_gridded_means_gt_700mm": all_gridded_gt_700,
            "point_rainfall": point,
            "decision_rule": {
                "gridded_load_pass": "all three accumulated means > 700 mm",
                "single_day_control_fails": "peak_day_share < 0.15",
                "persistence_pass": "heavy_days_ge_10mm >= 30 and longest_heavy_spell_days >= 10",
                "final_label": final_label,
            },
            "judge_anchors": {
                "required_metric_groups": [
                    "gridded accumulated rainfall over the declared comparison window",
                    "point total and peak-day concentration",
                    "wet and heavy-day persistence",
                    "maximum 14-day concentration",
                ],
                "weak_alternatives_to_reject": [
                    "single_day_only",
                    "report_wording_only",
                ],
            },
        },
        "rubric": RUBRIC,
        "tolerances": {
            "millimeter_values": 0.01,
            "share_values": 0.0005,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "Daily point-rainfall metrics use the full 2022-06-14 to 2022-10-01 event window; gridded precipitation means use their declared 2022-06-14 to 2022-07-29 package comparison window.",
        },
    }


def main() -> None:
    output = build_output()
    out_path = Path(__file__).resolve().parent / "computed_gt.json"
    out_path.write_text(json.dumps(output, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
